(function () {
  if (window.__ffHome || !document.body.classList.contains('index')) return;
  window.__ffHome = 1;
  var IDS = [1893857930, 989524931, 528958087, 448533154, 1993833332, 926222471, 452519602, 760028678];
  var best = null, tb = null;
  function mirror() {
    try {
      var o = getComputedStyle(tb).order;
      if (o && best.style.getPropertyValue('order') !== o) best.style.setProperty('order', o, 'important');
    } catch (e) {}
  }
  function fill() {
    var row = best.querySelector('.ffb-row');
    salla.api.product.fetch({ source: 'selected', source_value: IDS }).then(function (r) {
      var list = (r && r.data) || [];
      if (!list.length) return;
      list.forEach(function (p) {
        var c = document.createElement('custom-salla-product-card');
        c.className = 's-product-card-entry';
        c.product = p;
        row.appendChild(c);
      });
      best.classList.add('ffb-on');
    }).catch(function () {});
  }
  function buildBest() {
    if (best) return true;
    tb = document.getElementById('ff-trustbar');
    if (!tb || !window.salla || !salla.api || !salla.api.product || !customElements.get('custom-salla-product-card')) return false;
    best = document.createElement('section');
    best.id = 'ff-best';
    best.className = 's-block';
    best.innerHTML = '<div class="container"><h2 class="ffb-t">الأكثر طلباً هذا الشهر</h2><div class="s-products-list-wrapper s-products-list-vertical-cards ffb-row"></div></div>';
    tb.parentNode.insertBefore(best, tb.nextSibling);
    mirror();
    window.addEventListener('load', mirror);
    window.addEventListener('resize', mirror);
    fill();
    return true;
  }
  var moved = false;
  function order() {
    if (moved) return true;
    var how = document.getElementById('ff-how'), qa = document.getElementById('ff-qa');
    if (!how || !qa) return false;
    if (how.nextSibling !== qa) how.parentNode.insertBefore(qa, how.nextSibling);
    moved = true;
    return true;
  }
  var n = 0;
  var iv = setInterval(function () {
    n++;
    var a = buildBest(), b = order();
    if (best) mirror();
    if ((a && b && n > 40) || n > 80) clearInterval(iv);
  }, 250);
})();

